let tavReversePending = null;
function cancelTavReverse() {
  const pending=tavReversePending;if(!pending)return;
  tavReversePending=null;pending.animation?.cancel();pending.card.removeAttribute('aria-busy');
  const button=$('tav-pull');if(button){button.disabled=!tavReady();button.textContent=v571CanFree()?'Бесплатный призыв':'Призыв героя · '+PULL_COST+' 💎';}
}
function tavPull() {
  if(tavReversePending)return;
  if(tavBusy){tavBusy.skip();return;}
  if(!tavReady()){tvToast('Недостаточно камней призыва. Нужно '+PULL_COST+'.',2400);return;}
  const stage=$('tv-stage'),card=stage?.querySelector('.tv-card');
  if(!stage||!card||!stage.classList.contains('flip')||reduced||typeof card.animate!=='function'){tavPullResolved();return;}
  const pending={hero:S.hero,stage,card,animation:null};tavReversePending=pending;
  const button=$('tav-pull');button.disabled=true;button.textContent='Закрываем карту…';card.setAttribute('aria-busy','true');
  try{
    const start=getComputedStyle(card).transform;
    card.getAnimations?.().forEach(animation=>animation.cancel());
    pending.animation=card.animate([{transform:start},{transform:'rotateY(0deg)'}],{duration:600,easing:'ease-in-out',fill:'forwards'});
    pending.animation.finished.then(()=>{
      if(tavReversePending!==pending)return;
      if(S.hero!==pending.hero||!stage.isConnected||$('tavsheet').hidden||!tavReady()){cancelTavReverse();return;}
      tavReversePending=null;card.removeAttribute('aria-busy');button.disabled=false;
      try{tavPullResolved();}finally{pending.animation.cancel();}
    },()=>{if(tavReversePending===pending)cancelTavReverse();});
  }catch(_){cancelTavReverse();if(S.hero===pending.hero&&stage.isConnected&&!$('tavsheet').hidden&&tavReady())tavPullResolved();}
}
